actions.script:
const L = text => ec.l10n.localize(text)
const number = (value, pattern) => ec.l10n.format(Number(value), pattern || '#,##0')
const DASH = '—'
const notReported = L('Not reported by this platform')
const bytes = value => {
    if (value === null || value === undefined) return DASH
    const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    let amount = Number(value), unit = 0
    while (amount >= 1024 && unit < units.length - 1) { amount /= 1024; unit++ }
    return number(amount, amount >= 100 || unit === 0 ? '#,##0' : '#,##0.#') + ' ' + units[unit]
}
const percent = value => value === null || value === undefined ? DASH : number(value, '#,##0') + ' %'
const duration = milliseconds => {
    const minutes = Math.max(Math.floor(milliseconds / 60000), 0)
    const days = Math.floor(minutes / 1440), hours = Math.floor((minutes % 1440) / 60)
    if (days > 0) return days + ' d ' + hours + ' h'
    if (hours > 0) return hours + ' h ' + (minutes % 60) + ' min'
    return minutes + ' min'
}
// a level as a word and a theme color; a reading with no level (not reported) has neither
const LEVELS = {ok: {text: L('OK'), color: 'positive'}, warning: {text: L('Warning'), color: 'warning'},
    critical: {text: L('Critical'), color: 'negative'}}
const levelOf = name => LEVELS[name] || {text: DASH, color: 'grey-6'}
const flagged = name => name === 'warning' || name === 'critical'
const worse = (first, second) => [first, second].includes('critical') ? 'critical' : [first, second].includes('warning') ? 'warning' : first || second
// each read on its own: a failure is logged and the rest of the page still shows
const read = (name, body, fallback) => {
    try { return body() } catch (error) { ec.logger.error('System home: ' + name + ' failed: ' + String(error)); return fallback }
}

// ---- period ----
periodOptions = [{id: '1h', label: L('last hour')}, {id: '6h', label: L('last 6 hours')},
    {id: '24h', label: L('last 24 hours')}, {id: '7d', label: L('last 7 days')}]
period = periodOptions.some(option => option.id === period) ? period : '1h'
periodFrom = 'now-' + period
// auto refresh: seconds from the address, a minute at least (the metric documents' own pace), none by default
refreshSeconds = Number(refresh) > 0 ? Math.max(60, Math.round(Number(refresh))) : 0
instanceId = read('instance id', () => ec.factory.getInstanceId(), null)
activityVariables = instanceId ? {instance: instanceId} : {}
// The dashboard of the Activity strip: the administrator's own (the system_home_dashboard setting, a definition
// id) when it is there for this reader, else the shipped system-home. One that is not there is logged.
activityDashboard = 'system-home'
const ownDashboard = String(System.getProperty('system_home_dashboard') || '').trim()
if (ownDashboard && ownDashboard !== activityDashboard) {
    let own = null
    try { own = ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId: ownDashboard}).call()?.definition }
    catch (error) { own = null }
    if (ec.message.hasError()) { own = null; ec.message.clearErrors() }
    if (own && own.type === 'dashboard') activityDashboard = ownDashboard
    else ec.logger.warn('System home: the dashboard of system_home_dashboard, ' + ownDashboard + ', is not one this user may read; the shipped one is shown')
}

// ---- identity and state ----
const report = read('runtime report', () => ec.factory.getStartupReport(), null) || {}
const status = read('status map', () => ec.factory.getStatusMap(true), null) || {}
const system = status.System || {}, runtime = status.Runtime || {}, readings = status.Resources || {}
identityText = ['MR Moqui ' + (report.version || ec.factory.moquiVersion), report.package, report.purpose,
    report.role ? L('role') + ' ' + report.role : ''].filter(part => part).join(' · ')
const startMillis = runtime.Start != null ? Number(String(runtime.Start)) : NaN
const facts = [(status.Web || {}).HostName, [system.OsName, system.OsVersion].filter(part => part).join(' '), system.CPU,
    system.Processors ? number(system.Processors) + ' ' + L('processors') : '']
if (Number.isFinite(startMillis)) facts.push(L('up') + ' ' + duration(Date.now() - startMillis) + ' (' + L('since') + ' ' +
    ec.l10n.format(runtime.Start, 'MMM d, HH:mm') + ')')
if (report.readySeconds != null) facts.push(L('ready in') + ' ' + number(report.readySeconds, '#,##0.0') + ' s')
factsText = facts.filter(part => part).join(' · ')
const componentCount = read('components', () => Array.from(ec.factory.getComponentInfoList() || []).length, 0)
componentsText = number(componentCount) + ' ' + (componentCount === 1 ? L('component') : L('components'))
systemState = status.Draining === true ? {text: L('Draining'), color: 'warning'}
    : status.Ready === true ? {text: L('Ready'), color: 'positive'} : {text: L('Not ready'), color: 'negative'}
nowText = ec.l10n.format(ec.user.nowTimestamp, 'HH:mm:ss')
requestDetails = read('request details', () => ec.web.getRequestDetails(), '')
const statusIps = String(System.getProperty('webapp_status_ips') || '').trim()
statusReadersText = statusIps
    ? L('Both answer only requests from this machine and from these addresses (webapp_status_ips):') + ' ' + statusIps
    : L('Both answer only requests from this machine; webapp_status_ips names other addresses that may read them.')

// ---- needs attention ----
const SEVERITIES = {critical: {text: L('Critical'), color: 'negative'}, warning: {text: L('Warning'), color: 'warning'},
    info: {text: L('Note'), color: 'info'}}
// the service writes absolute routes; a System screen is linked from here, since another app mounts System too
const screenLink = link => !link ? '' : link.startsWith('/apps/system/') ? '../' + link.slice('/apps/system/'.length) : '/' + link
attentionAvailable = false; attentionItems = []; attentionCount = 0; attentionCheckedText = ''
read('attention', () => {
    const out = ec.service.sync().name('moqui.tools.SystemHomeServices.get#SystemAttention').call() || {}
    if (ec.message.hasError()) {
        const errors = ec.message.getErrorsString()
        ec.message.clearErrors()
        throw new Error(errors)
    }
    attentionItems = Array.from(out.items || []).map(item => {
        const severity = SEVERITIES[item.severity] || SEVERITIES.info
        return {severityText: severity.text, severityColor: severity.color, itemText: String(item.text || ''),
            itemLink: screenLink(item.link), itemParameters: item.parameters || {}}
    })
    attentionCount = attentionItems.length
    attentionCheckedText = out.checkedDate != null ? ec.l10n.format(out.checkedDate, 'HH:mm:ss') : nowText
    attentionAvailable = true
})
attentionCountText = attentionCount === 1 ? L('1 needs attention') : number(attentionCount) + ' ' + L('need attention')

// ---- counters ----
const cpu = readings.Cpu || {}, memory = readings.Memory || {}, swap = readings.Swap || {}, files = readings.OpenFiles || {}
const filesystems = Array.from(readings.Filesystems || [])
// a counter at a warning or critical level takes that color, and says the level in its title
const card = (title, value, level) => ({title: flagged(level) ? title + ' · ' + levelOf(level).text : title, value,
    style: flagged(level) ? 'text-' + levelOf(level).color : ''})
loadCard = card(L('Load, 5 minutes'), percent(cpu.LoadPercent), cpu.Level)
memoryCard = card(memory.ProcessPercent != null && memory.LimitBytes != null
    ? L('Memory') + ' · ' + percent(memory.ProcessPercent) + ' ' + L('of') + ' ' + bytes(memory.LimitBytes) : L('Memory'),
    bytes(memory.ProcessBytes), memory.Level)
const fullest = filesystems.filter(filesystem => filesystem.usedPercent != null)
    .sort((first, second) => Number(second.usedPercent) - Number(first.usedPercent))[0]
diskCard = card(fullest ? L('Disk') + ' ' + fullest.mountPoint : L('Disk'), fullest ? percent(fullest.usedPercent) : DASH,
    fullest ? fullest.level : null)
const workers = read('worker pool', () => {
    const pool = ec.factory.workerPool
    return {active: pool.activeCount, maximum: pool.maximumPoolSize, queued: pool.queueSize, capacity: pool.remainingCapacity}
}, null)
workersCard = workers
    ? card(L('Workers') + ' · ' + number(workers.queued) + ' ' + L('queued'), number(workers.active) + ' ' + L('of') + ' ' + number(workers.maximum),
        workers.maximum > 0 && (workers.active >= workers.maximum || workers.capacity <= 0) ? 'warning' : null)
    : card(L('Workers'), DASH, null)
// one row per connection pool: entity groups on one database share it
const pools = []
for (const source of Array.from(status.DataSources || [])) {
    let pool = pools.find(candidate => candidate.uniqueName === source.uniqueName)
    if (!pool) { pool = Object.assign({groups: []}, source); pools.push(pool) }
    pool.groups.push(String(source.group))
}
const sum = name => pools.reduce((total, pool) => total + Number(pool[name] || 0), 0)
poolCard = pools.length
    ? card(L('Database connections') + ' · ' + number(sum('waiting')) + ' ' + L('waiting'),
        number(sum('checkedOut')) + ' ' + L('of') + ' ' + number(sum('max')), sum('waiting') > 0 ? 'warning' : null)
    : card(L('Database connections'), DASH, null)
const usersToday = Array.from(usersTodayList).length
usersTodayText = usersToday >= 1000 ? '1,000+' : number(usersToday)

// ---- activity ----
const integrations = Array.from(report.integrations || []), listeners = Array.from(report.listeners || [])
const notBuilt = Array.from(report.notBuilt || []).map(entry => String(entry && entry.name ? entry.name : entry))
const telemetry = integrations.find(entry => entry.name === 'Telemetry')
// a process that reported no Telemetry entry (a test, a command) follows the setting
const telemetryState = notBuilt.includes('Telemetry') ? 'notBuilt' : telemetry ? telemetry.state
    : String(System.getProperty('telemetry_enabled') || '') === 'false' ? 'off' : 'on'
telemetryOn = telemetryState === 'on'
telemetryOffText = telemetryState === 'notBuilt' ? L('Telemetry is not in this build, so there is no history.')
    : L('Telemetry is off, so there is no history.') + ' ' + (telemetry && telemetry.detail ? telemetry.detail
        : L('The setting is telemetry_enabled.'))

// the counters' sparklines: each gauge's values over the period, when there is telemetry to read
counterSeries = telemetryOn ? read('counter series', () => ec.service.sync().name('moqui.tools.SystemHomeServices.get#CounterSeries')
    .parameters({from: periodFrom, instanceId: instanceId}).call()?.series || {}, {}) : {}

// ---- resources ----
resourceRows = []
const resource = (name, text, level, metricName, tooltip) => resourceRows.push({name, text, levelText: levelOf(level).text,
    levelColor: levelOf(level).color, metricName: metricName || '', tooltip: text === DASH ? notReported : tooltip || ''})
resource(L('CPU load'), cpu.LoadPercent != null
    ? percent(cpu.LoadPercent) + ' ' + L('of') + ' ' + number(cpu.Processors) + ' ' + L('processors') + ' · ' +
        [cpu.Load1, cpu.Load5, cpu.Load15].map(load => number(load, '#,##0.00')).join(', ') + ' ' + L('over 1, 5 and 15 minutes')
    : DASH, cpu.Level, 'moqui.system.cpu.load.utilization', L('The level follows the 5-minute load as a share of the processors'))
resource(L('This process, CPU'), cpu.ProcessPercent != null ? percent(cpu.ProcessPercent) + ' ' + L('of the processors') : DASH, null,
    'process.cpu.utilization', L('The share of the processors this process used since the readings were last taken'))
resource(L('This process, memory'), memory.ProcessBytes != null
    ? bytes(memory.ProcessBytes) + (memory.LimitBytes != null ? ' ' + L('of') + ' ' + bytes(memory.LimitBytes) + ' (' + percent(memory.ProcessPercent) + ')' : '') +
        (memory.ProcessPeakBytes != null ? ' · ' + L('peak') + ' ' + bytes(memory.ProcessPeakBytes) : '')
    : DASH, memory.Level, 'moqui.process.memory.utilization',
    memory.LimitSource === 'container' ? L('The limit in force is the container\'s') : L('The limit in force is the machine\'s memory'))
resource(L('Machine memory'), memory.AvailableBytes != null
    ? bytes(memory.AvailableBytes) + ' ' + L('of') + ' ' + bytes(memory.TotalBytes) + ' ' + L('available') + ' (' + percent(memory.AvailablePercent) + ')'
    : DASH, memory.AvailableLevel, 'system.linux.memory.available', '')
for (const filesystem of filesystems) {
    const inodes = filesystem.inodesUsedPercent != null ? ' · ' + percent(filesystem.inodesUsedPercent) + ' ' + L('of its file entries used') : ''
    const holds = Array.from(filesystem.holds || []).join(', ')
    resource(L('Disk') + ' ' + filesystem.mountPoint, filesystem.usedPercent != null
        ? percent(filesystem.usedPercent) + ' ' + L('of') + ' ' + bytes(filesystem.totalBytes) + ', ' + bytes(filesystem.availableBytes) + ' ' + L('free') + inodes +
            (holds ? ' · ' + holds : '')
        : DASH, worse(filesystem.level, filesystem.inodesLevel), 'system.filesystem.utilization',
        L('The space the server\'s user may still write, and what of the instance is on this filesystem'))
}
if (!filesystems.length) resource(L('Disk'), DASH, null, '', '')
resource(L('Open files'), files.Count != null
    ? number(files.Count) + (files.Limit != null ? ' ' + L('of') + ' ' + number(files.Limit) : '')
    : DASH, files.Level, 'process.unix.file_descriptor.count', '')
if (Number(swap.TotalBytes || 0) > 0) resource(L('Swap'), percent(swap.UsedPercent) + ' ' + L('of') + ' ' + bytes(swap.TotalBytes) + ' ' + L('used'),
    swap.Level, '', '')
// each certificate the HTTPS listener serves, the soonest to expire first
for (const certificate of Array.from(readings.Certificates || [])) {
    const days = Math.floor(Number(certificate.daysLeft))
    resource(L('Certificate') + ' ' + certificate.name, (days < 0 ? L('Expired') : days + ' ' + L('days left')) + ' · ' + L('until') + ' ' +
        ec.l10n.format(new Date(Number(certificate.notAfter)), 'yyyy-MM-dd'), certificate.level, 'moqui.tls.certificate.days_left',
        L('When the certificate in runtime/cert stops being valid; System › Certificates shows each name and renews those set up with ACME'))
}
// a meter beside each reading that is a share: how full, by its row's name
const shares = {}
shares[L('CPU load')] = cpu.LoadPercent
shares[L('This process, CPU')] = cpu.ProcessPercent
shares[L('This process, memory')] = memory.ProcessPercent
shares[L('Machine memory')] = memory.AvailablePercent != null ? 100 - Number(memory.AvailablePercent) : null
for (const filesystem of filesystems) shares[L('Disk') + ' ' + filesystem.mountPoint] = filesystem.usedPercent
shares[L('Open files')] = files.Count != null && Number(files.Limit) > 0 ? 100 * Number(files.Count) / Number(files.Limit) : null
shares[L('Swap')] = swap.UsedPercent
for (const row of resourceRows) {
    const share = shares[row.name]
    row.meterShown = share != null && isFinite(Number(share))
    const filled = row.meterShown ? Math.min(1, Math.max(0, Number(share) / 100)) : 0
    row.meterValue = filled.toFixed(3)
    row.meterPercent = Math.round(filled * 100)
    // ten cells in the terminal
    row.meterBar = row.meterShown ? '█'.repeat(Math.round(filled * 10)) + '░'.repeat(10 - Math.round(filled * 10)) : ''
    row.meterColor = ['warning', 'negative'].includes(row.levelColor) ? row.levelColor : 'primary'
}

// ---- database ----
const BACKUP_SERVICE = 'org.moqui.impl.ServerServices.backup#EmbeddedDatabase'
const backupText = pools.some(pool => pool.embedded === true) ? read('backup job', () => {
    const jobs = Array.from(ec.entity.find('moqui.service.job.ServiceJob').condition('serviceName', BACKUP_SERVICE).limit(20).list())
    if (!jobs.length) return L('no backup job')
    return jobs.some(job => job.paused !== 'Y' && job.cronExpression) ? L('backup scheduled') : L('backup paused')
}, DASH) : ''
databaseRows = pools.map(pool => {
    const db = 'group:' + pool.groups[0]
    // what the database says of itself, kept five minutes by the service; left out for a user who may not ask
    const facts = read('database ' + db, () => {
        const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.get#Capabilities').parameters({db}).call() || {}
        if (ec.message.hasError()) { ec.message.clearErrors(); return {} }
        return out
    }, {})
    ec.message.clearErrors()
    // "PostgreSQL 18.6 on x86_64-pc-linux-gnu, compiled by ..." is shown as its name and number
    const product = /^[A-Za-z]+ [0-9][0-9.]*/.exec(String(facts.version || ''))
    return {db, groupsText: pool.groups.join(', '),
        kindText: [pool.embedded === true ? L('embedded') : '', product ? product[0] : [pool.database, facts.version].filter(part => part).join(' ')]
            .filter(part => part).join(' '),
        sizeText: facts.databaseSize != null ? bytes(facts.databaseSize) : DASH,
        sizeTooltip: facts.databaseSize != null ? '' : L('The database did not report its size to this user'),
        poolText: number(pool.checkedOut || 0) + ' ' + L('of') + ' ' + number(pool.max || 0) + ' · ' + number(pool.waiting || 0) + ' ' + L('waiting'),
        backupText: pool.embedded === true ? backupText : L('external')}
})

// ---- cluster members: only when there is more than one (the Cluster listener is on for every server) ----
clusterRows = read('cluster members', () => {
    const members = Array.from(ec.entity.find('moqui.server.ClusterMember').limit(50).list())
    if (members.length < 2) return []
    return members.map(member => ({instanceId: String(member.instanceId) + (member.instanceId === instanceId ? ' (' + L('this server') + ')' : ''),
        clusterBaseUrl: member.clusterBaseUrl || DASH,
        heartbeatText: member.heartbeat != null ? duration(Date.now() - Number(String(member.heartbeat))) + ' ' + L('ago') : DASH}))
}, [])

// ---- listeners and integrations: failed and skipped first, each with the screen that configures it ----
const STATES = {failed: {text: L('Failed'), color: 'negative', order: 0}, skipped: {text: L('Skipped'), color: 'warning', order: 1},
    on: {text: L('On'), color: 'positive', order: 2}, off: {text: L('Off'), color: 'grey-6', order: 3}}
const fullPath = Array.from(sri.getScreenUrlInfo().fullPathNameList || [])
const mounted = new Set(read('system menu', () => Array.from(sri.getMenuItems('/' + fullPath.slice(0, -1).join('/')) || [])
    .map(item => String(item.name)), []))
const SCREENS = [[/^search/i, '//apps/tools/Data/Documents'], [/^telemetry/i, '../Monitor/Sources'], [/^(llm|mcp|a2a)/i, '../Llm'],
    [/^edge/i, '../EdgeNode'], [/^schedul/i, '../ServiceJob'], [/^(pdf|ipp|print)/i, '../Print'],
    [/^(call|sip|turn)/i, mounted.has('Voice') ? '../Voice' : '../Conf'], [/^(xmpp|chat)/i, mounted.has('ChatBridges') ? '../ChatBridges' : '../Conf'],
    [/^sso/i, '../Security']]
const entryRows = entries => entries.map((entry, index) => {
    const state = STATES[entry.state] || {text: String(entry.state || DASH), color: 'grey-6', order: 4}
    const screen = SCREENS.find(candidate => candidate[0].test(String(entry.name)))
    return {name: String(entry.name), detail: String(entry.detail || ''), stateText: state.text, stateColor: state.color,
        order: state.order * 1000 + index, screenLink: screen ? screen[1] : '../Conf'}
}).sort((first, second) => first.order - second.order)
listenerRows = entryRows(listeners)
integrationRows = entryRows(integrations)
toolsText = Array.from(report.tools || []).map(tool => String(tool && tool.name ? tool.name : tool)).join(', ')
notBuiltText = notBuilt.join(', ')
routesText = Array.from(report.routes || []).join('\n')

// ---- navigation: the catalog of template/HomeParts.xml (a component adds entries with an actions-extend) ----
const featured = (path, title, text, links) => ({path, title, text, links, featured: true})
const entry = (group, path, title, icon) => ({group, path, title, icon})
const server = L('Server'), monitor = L('Monitor'), integration = L('Integration'),
    administration = L('Administration'),
    ai = L('AI'), content = L('Content')
navOptions = {otherTitle: L('More')}
navCatalog = [
    featured('Monitor', '', L('Traces, logs, errors, metrics and incidents')),
    featured('Security', L('Users and access'), L('Accounts, groups and what each may reach'),
        [{path: 'Access/Groups'}, {path: 'Access/Capabilities'}, {path: 'Security/Sessions'}]),
    featured('Operations', '', L('Jobs, their runs and notification topics')),
    featured('Conf', '', L('Settings and the file each came from')),
    featured('Components', '', L('What is loaded; deploy and update')),

    entry(server, 'Cache'), entry(server, 'ThreadList'), entry(server, 'TerminalSessions', '', 'sym_o_terminal'),
    entry(server, 'Print/Printer', '', 'sym_o_print'), entry(server, 'Print/PrintJob', '', 'sym_o_receipt_long'), entry(server, 'Instance'),
    entry(server, 'Certificates', '', 'sym_o_verified_user'),

    entry(administration, 'Security/UserAccount', '', 'sym_o_person'), entry(administration, 'Access/Groups', '', 'sym_o_group'),
    entry(administration, 'Access/Capabilities', '', 'sym_o_rule'), entry(administration, 'Access/RowRules', '', 'sym_o_filter_alt'),
    entry(administration, 'Access/ArtifactGroups', '', 'sym_o_key'), entry(administration, 'Security/SignInPolicy', '', 'sym_o_password'),
    entry(administration, 'Security/IdentityProviders', '', 'sym_o_passkey'), entry(administration, 'Security/Sessions', '', 'sym_o_devices'),
    entry(administration, 'Operations/Jobs', '', 'sym_o_schedule'), entry(administration, 'Operations/JobRuns', '', 'sym_o_history'),
    entry(administration, 'Operations/Topics', '', 'sym_o_notifications'),
    entry(administration, 'Operations/Health', '', 'sym_o_health_and_safety'),
    entry(administration, 'Settings/InstanceSettings', L('Instance settings'), 'sym_o_tune'),
    entry(administration, 'Settings/Localization', '', 'sym_o_translate'),
    entry(administration, 'Settings/SettingsHome', L('Settings index'), 'sym_o_list_alt'),
    entry(administration, 'Data/Imports', '', 'sym_o_upload_file'), entry(administration, 'Data/Exports', '', 'sym_o_file_download'),
    entry(administration, 'Data/Backups', '', 'sym_o_backup'),
    entry(administration, 'Audit/AuditChanges', L('Audit changes'), 'sym_o_history_edu'), entry(administration, 'Visit'),

    entry(monitor, 'Monitor/Services'), entry(monitor, 'Monitor/Traces'), entry(monitor, 'Monitor/Logs'), entry(monitor, 'Monitor/Errors'),
    entry(monitor, 'Monitor/Metrics'), entry(monitor, 'Monitor/Incidents'), entry(monitor, 'Monitor/Checks'), entry(monitor, 'Monitor/Settings'),
    entry(monitor, 'Monitor', L('All of Monitor')),

    entry(integration, 'Integrations/Connections', '', 'sym_o_hub'), entry(integration, 'Integrations/SystemMessages', '', 'sym_o_swap_horiz'),
    entry(integration, 'Integrations/MessageTypes', '', 'sym_o_schema'),
    entry(integration, 'Protocols/Home', L('Mail and protocols'), 'sym_o_lan'), entry(integration, 'Protocols/MailRelays', '', 'sym_o_outgoing_mail'),
    entry(integration, 'Protocols/MailQueue', '', 'sym_o_outbox'), entry(integration, 'Protocols/ServerConfiguration', '', 'sym_o_dns'),
    entry(integration, 'EntitySync'), entry(integration, 'EdgeNode'), entry(integration, 'EdgeClients'),
    // Voice and Chat Bridges are basic-comms' screens: it adds their entries to this group (its screen-extend)

    entry(ai, 'Llm/Dashboard', L('Overview'), 'sym_o_dashboard'), entry(ai, 'Llm/Models', '', 'sym_o_model_training'),
    entry(ai, 'Llm/Tools', '', 'sym_o_construction'), entry(ai, 'Llm/Runs', '', 'sym_o_play_circle'),
    entry(ai, 'Llm/Approvals', '', 'sym_o_approval'), entry(ai, 'Llm/Usage', '', 'sym_o_payments'),
    entry(ai, 'Llm/Traces', '', 'sym_o_timeline'), entry(ai, 'Llm/Evals', '', 'sym_o_grading'), entry(ai, 'Constitution'),

    entry(content, 'Resource')
]
